package dev.gray.companion.core

import java.util.UUID
import kotlinx.serialization.Serializable
import kotlinx.serialization.Transient
import kotlinx.serialization.json.JsonElement

fun newId(): String = UUID.randomUUID().toString()
@Serializable enum class Role { SYSTEM, USER, ASSISTANT }
@Serializable enum class Compare { EQUALS, NOT_EQUALS, GREATER, GREATER_OR_EQUAL, LESS, LESS_OR_EQUAL, EXISTS }
@Serializable data class Condition(val key: String = "", val op: Compare = Compare.EQUALS, val value: String = "", val expression: String = "")
