    val inputProcessing: List<TextProcessStep> = emptyList(), val outputProcessing: List<TextProcessStep> = emptyList(),
    val macroProcess: MacroProcessConfig = MacroProcessConfig(), val arguments: Map<String, String> = emptyMap())
@Serializable data class PromptBlock(val id: String = newId(), val title: String = "提示词", val template: String = "", val role: Role = Role.SYSTEM, val enabled: Boolean = true, val hideWhenReferencesEmpty: Boolean = false, val condition: Condition? = null, val position: PromptPosition = PromptPosition.BEFORE_HISTORY, val depth: Int = 0, val recognition: Recognition? = null, val processing: List<TextProcessStep> = emptyList(), val slug: String = "", val tagIds: List<String> = emptyList())
@Serializable data class WorkflowNode(val id: String = newId(), val title: String = "生成", val actionId: String = "model.generate", val dependsOn: List<String> = emptyList(), val blocks: List<PromptBlock> = emptyList(), val inputTemplate: String = "{{input}}", val outputKey: String = "reply", val visible: Boolean = false, val includeHistory: Boolean = true, val enabled: Boolean = true, val condition: Condition? = null, val arguments: Map<String, String> = emptyMap(), val resultCategory: String = "", val outputSlot: OutputSlot = OutputSlot.BODY, val recognition: Recognition? = null, val explicitHistory: Boolean = false, val inputProcessing: List<TextProcessStep> = emptyList(), val outputProcessing: List<TextProcessStep> = emptyList(), val generation: ModelCallOptions = ModelCallOptions(), val macroProcess: MacroProcessConfig = MacroProcessConfig(), val legacyAction: LegacyActionBackup? = null, val slug: String = "", val tagIds: List<String> = emptyList(), val regexOutputCopy: RegexOutputCopy = RegexOutputCopy(), val recordTrajectory: Boolean = true)
